package main

import (
	"encoding/csv"
	"fmt"
	"io"
	"time"
)

// FormatAmount renders cents as a decimal amount with two decimal places.
func FormatAmount(cents int64) string {
	return fmt.Sprintf("%.2f", float64(cents)/100)
}

// Total adds up every entry's amount.
func Total(entries []Entry) int64 {
	var total int64
	for _, e := range entries {
		total += e.Cents
	}
	return total
}

// WriteCSV writes the entries as CSV with a header row.
func WriteCSV(w io.Writer, entries []Entry) error {
	cw := csv.NewWriter(w)
	if err := cw.Write([]string{"date", "amount", "memo"}); err != nil {
		return err
	}
	for _, e := range entries {
		if err := cw.Write([]string{e.Date.Format("2006-01-02"), FormatAmount(e.Cents), e.Memo}); err != nil {
			return err
		}
	}
	cw.Flush()
	return cw.Error()
}
```

